pub(super) fn snap(e:&mut Editor){if !e.max.snap_objects||e.gizmo!=0||e.drag_start.is_none(){return;}let candidates=e.project.objects.iter().filter(|o|Some(o.id)!=e.selected&&!e.pro.multi.contains(&o.id)).map(|o|o.position).collect::<Vec<_>>();let tolerance=8./e.zoom.max(0.2);for o in e.project.objects.iter_mut().filter(|o|Some(o.id)==e.selected||e.pro.multi.contains(&o.id)){for axis in 0..2{if e.tools.axis!=0&&e.tools.axis!=axis+1{continue;}if let Some(v)=candidates.iter().map(|p|p[axis]).filter(|v|(*v-o.position[axis]).abs()<=tolerance).min_by(|a,b|(*a-o.position[axis]).abs().total_cmp(&(*b-o.position[axis]).abs())){o.position[axis]=v;}}}}

pub(super) fn dock_tabs(ui:&mut egui::Ui,e:&mut Editor){ui.horizontal_wrapped(|ui|{for (i,label) in [tr(e.uk,"Сцена","Scene"),tr(e.uk,"Інспектор","Inspector"),tr(e.uk,"Інструменти","Tools")].iter().enumerate(){let r=ui.add(egui::Label::new(*label).sense(egui::Sense::click_and_drag()));r.dnd_set_drag_payload(i);r.context_menu(|ui|{for (zone,name) in ["Left","Right","Bottom","Top","Float"].iter().enumerate(){if ui.button(*name).clicked(){if zone<4{e.master.settings.dock[i]=zone;}match i{0=>e.workspace.prefs.scene=zone==4,1=>e.workspace.prefs.inspector=zone==4,_=>e.workspace.prefs.bottom=zone==4};ui.close_menu();}}});}if ui.small_button("Save dock").clicked(){super::master::save(e);super::workspace::save(e);}ui.separator();for (zone,label) in [tr(e.uk,"Ліворуч","Left"),tr(e.uk,"Праворуч","Right"),tr(e.uk,"Знизу","Bottom"),tr(e.uk,"Зверху","Top")].iter().enumerate(){let r=ui.button(*label);if let Some(i)=r.dnd_release_payload::<usize>(){if *i<3{e.master.settings.dock[*i]=zone;match *i{0=>e.workspace.prefs.scene=false,1=>e.workspace.prefs.inspector=false,_=>e.workspace.prefs.bottom=false};}}}let r=ui.button(tr(e.uk,"Плаваюча","Float"));if let Some(i)=r.dnd_release_payload::<usize>(){match *i{0=>e.workspace.prefs.scene=true,1=>e.workspace.prefs.inspector=true,2=>e.workspace.prefs.bottom=true,_=>{}}}});}

fn dependency_canvas(ui:&mut egui::Ui,db:&forge_engine::AssetDatabase,owner:&mut String,id:egui::Id){ui.collapsing("Dependency canvas",|ui|{let current=owner.clone();let Some(edges)=db.graph.get(&current)else{return;};let mut next=None;egui::ScrollArea::both().max_height(320.).show(ui,|ui|{let n=edges.len().min(128);let(r,_)=ui.allocate_exact_size(egui::vec2(ui.available_width().max(480.),(n as f32*29.+56.).max(80.)),egui::Sense::hover());let p=ui.painter_at(r);p.rect_filled(r,4.,ui.visuals().extreme_bg_color);let root=egui::Rect::from_min_size(r.min+egui::vec2(8.,8.),egui::vec2(r.width()-16.,28.));p.rect_filled(root,3.,ui.visuals().selection.bg_fill);p.text(root.left_center()+egui::vec2(6.,0.),egui::Align2::LEFT_CENTER,&current,egui::FontId::proportional(11.),ui.visuals().text_color());for(i,edge)in edges.iter().take(n).enumerate(){let node=egui::Rect::from_min_size(r.min+egui::vec2(34.,44.+i as f32*29.),egui::vec2(r.width()-42.,25.));let stem=egui::pos2(root.left()+12.,node.center().y);let stroke=egui::Stroke::new(1.,ui.visuals().widgets.inactive.bg_stroke.color);p.line_segment([egui::pos2(stem.x,root.bottom()),stem],stroke);p.line_segment([stem,node.left_center()],stroke);let document=db.graph.contains_key(edge);let missing=!document&&db.entries.get(edge).is_none_or(|a|!a.present);let response=ui.interact(node,id.with(("asset_node34",i)),egui::Sense::click());if response.clicked()&&document{next=Some(edge.clone());}p.rect_filled(node,3.,ui.visuals().widgets.inactive.bg_fill);p.text(node.left_center()+egui::vec2(5.,0.),egui::Align2::LEFT_CENTER,edge,egui::FontId::proportional(11.),if missing{egui::Color32::LIGHT_RED}else{ui.visuals().text_color()});response.on_hover_text(if document{"Open dependency"}else if missing{"Missing resource"}else{"Asset"});}});if let Some(next)=next{ui.ctx().data_mut(|d|d.insert_temp(id.with("back"),current));*owner=next;}});}

fn recursive_asset_canvas(ui:&mut egui::Ui,db:&forge_engine::AssetDatabase,owner:&mut String,id:egui::Id){ui.collapsing("Recursive asset graph / Filter",|ui|{
 let cache=egui::Id::new("recursive_asset35");let rows=match ui.ctx().data(|d|d.get_temp::<(String,std::sync::Arc<Vec<forge_engine::AssetGraphNode>>)>(cache)){Some((n,r)) if n==*owner=>r,_=>{let r=std::sync::Arc::new(db.dependency_nodes(owner));ui.ctx().data_mut(|d|d.insert_temp(cache,(owner.clone(),r.clone())));r}};
 let(mut query,mut missing)=ui.ctx().data(|d|d.get_temp::<(String,bool)>(id.with("filter35"))).unwrap_or_default();ui.horizontal(|ui|{ui.label("Search");ui.text_edit_singleline(&mut query);ui.checkbox(&mut missing,"Missing only");});ui.ctx().data_mut(|d|d.insert_temp(id.with("filter35"),(query.clone(),missing)));let q=query.to_lowercase();let mut next=None;
 egui::ScrollArea::both().max_height(360.).show(ui,|ui|{for row in rows.iter().filter(|r|(!missing||r.missing)&&(q.is_empty()||r.path.to_lowercase().contains(&q))){ui.horizontal(|ui|{ui.add_space(row.depth as f32*14.);let icon=if row.missing{"!"}else if row.repeated{"↺"}else if db.graph.contains_key(&row.path){"▣"}else{"▪"};let label=format!("{icon} {}",row.path);if ui.selectable_label(row.path==*owner,egui::RichText::new(label).color(if row.missing{egui::Color32::LIGHT_RED}else{ui.visuals().text_color()})).clicked()&&db.graph.contains_key(&row.path){next=Some(row.path.clone());}});}});if let Some(n)=next{ui.ctx().data_mut(|d|d.insert_temp(id.with("back"),owner.clone()));*owner=n;}ui.small(format!("{} nodes (bounded: 512 nodes, depth 16); repeated/cyclic links shown once per edge",rows.len()));
 });}
